-- PostgreSQL twin of migrations/0069_b2b_accounts.sql, generated by scripts/sqlite_to_pg_migration.py

-- B2B-first launch: organizations and retail shops as buyers, phone invitations, account applications.
ALTER TABLE organizations ADD COLUMN buyer_kind TEXT NOT NULL DEFAULT 'organization' CHECK (buyer_kind IN ('organization', 'retailer'));

ALTER TABLE organizations ADD COLUMN business_license_no TEXT;

ALTER TABLE organizations ADD COLUMN city TEXT;

-- An invitation by mobile number: claimed automatically the first time that number is verified (OTP login or link).
CREATE TABLE IF NOT EXISTS b2b_invites (
    id                 BIGSERIAL PRIMARY KEY,
    organization_id    INTEGER NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    phone              TEXT NOT NULL CHECK (length(phone) = 11),
    role               TEXT NOT NULL CHECK (role IN ('employee', 'organization_admin', 'procurement_agent', 'organization_finance')),
    status             TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'claimed', 'revoked')),
    invited_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    claimed_user_id    INTEGER REFERENCES users(id) ON DELETE SET NULL,
    created_at         TEXT NOT NULL,
    claimed_at         TEXT,
    UNIQUE (organization_id, phone)
);

CREATE INDEX IF NOT EXISTS ix_b2b_invites_phone ON b2b_invites(phone, status);

-- Public "open a business account" requests. Closed ecosystem: an admin reviews every one.
CREATE TABLE IF NOT EXISTS b2b_applications (
    id                  BIGSERIAL PRIMARY KEY,
    buyer_kind          TEXT NOT NULL CHECK (buyer_kind IN ('organization', 'retailer')),
    legal_name          TEXT NOT NULL CHECK (length(legal_name) BETWEEN 2 AND 200),
    national_id         TEXT,
    business_license_no TEXT,
    contact_name        TEXT NOT NULL CHECK (length(contact_name) BETWEEN 2 AND 120),
    phone               TEXT NOT NULL CHECK (length(phone) = 11),
    city                TEXT,
    staff_band          TEXT CHECK (staff_band IS NULL OR staff_band IN ('1-10', '11-50', '51-200', '201-1000', '1000+')),
    monthly_band        TEXT CHECK (monthly_band IS NULL OR monthly_band IN ('<100m', '100m-500m', '500m-2b', '2b+')),
    message             TEXT CHECK (message IS NULL OR length(message) <= 1000),
    status              TEXT NOT NULL DEFAULT 'new' CHECK (status IN ('new', 'approved', 'rejected')),
    review_note         TEXT,
    reviewed_by_user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
    organization_id     INTEGER REFERENCES organizations(id) ON DELETE SET NULL,
    ip_address          TEXT,
    created_at          TEXT NOT NULL,
    reviewed_at         TEXT
);

CREATE INDEX IF NOT EXISTS ix_b2b_applications_status ON b2b_applications(status, created_at);

CREATE INDEX IF NOT EXISTS ix_b2b_applications_phone ON b2b_applications(phone, created_at);

-- Idempotency of the one-step onboarding (one row per Idempotency-Key).
CREATE TABLE IF NOT EXISTS b2b_onboardings (
    idempotency_key TEXT PRIMARY KEY,
    fingerprint     TEXT NOT NULL,
    organization_id INTEGER NOT NULL REFERENCES organizations(id),
    created_at      TEXT NOT NULL
);
